// Some portions generated by Claude
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Differential run develop vs branch (WP9 3.11.6, Layer 3): an expression error inside an EXISTS body must behave like
 * any other SPARQL expression error (BIND leaves its variable unbound, a condition evaluates to false). The branch
 * substitutes the outer solution into the body as constants and precompiles it per probe
 * ({@code FilterIterator.evaluateSubstitutedExists}), where {@code DefaultEvaluationStrategy.prepare} folds e.g.
 * {@code :b + 1} and the {@code ValueExprEvaluationException} escapes precompilation. Develop returns the expected rows
 * for every query below.
 */
public class ExistsSubstitutionExpressionErrorTest {

	private static final String PREFIX = "PREFIX : <http://ex/>\n";

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private void load(String trig) throws Exception {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader("@prefix : <http://ex/> .\n" + trig), "http://ex/", RDFFormat.TRIG);
		}
	}

	private List<String> rows(String query, String... vars) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			TupleQuery tupleQuery = conn.prepareTupleQuery(PREFIX + query);
			List<String> result = new ArrayList<>();
			try (TupleQueryResult res = tupleQuery.evaluate()) {
				for (BindingSet bs : res) {
					StringBuilder sb = new StringBuilder();
					for (String var : vars) {
						sb.append(var).append('=').append(bs.getValue(var)).append(' ');
					}
					result.add(sb.toString().trim());
				}
			}
			return result.stream().sorted().collect(Collectors.toList());
		}
	}

	/** Branch: ValueExprEvaluationException "Both arguments must be literals". */
	@Test
	public void bindErrorOnCorrelatedVariableInsideExistsLeavesVariableUnbound() throws Exception {
		load(":b :q :a .\n");
		String query = "SELECT ?o WHERE { ?o :q ?z FILTER EXISTS { ?o :q ?y . BIND(?o + 1 AS ?s) } }";
		assertEquals(List.of("o=http://ex/b"), rows(query, "o"));
	}

	/** Branch: no rows (the lone BIND makes the body empty instead of yielding one solution). */
	@Test
	public void existsBodyWithOnlyAnErroringBindHasOneSolution() throws Exception {
		load(":b :q :a .\n");
		String query = "SELECT ?o WHERE { ?o :q ?z FILTER EXISTS { BIND(?o + 1 AS ?s) } }";
		assertEquals(List.of("o=http://ex/b"), rows(query, "o"));
	}

	/** Branch: ValueExprEvaluationException. The body has no match, so NOT EXISTS keeps the row. */
	@Test
	public void bindErrorOnCorrelatedVariableInsideNotExistsKeepsRow() throws Exception {
		load(":b :p :d .\n");
		String query = "SELECT ?o ?x WHERE { ?o :p ?x . FILTER NOT EXISTS { ?o :r ?o . BIND(?o + 1 AS ?w) } }";
		assertEquals(List.of("o=http://ex/b x=http://ex/d"), rows(query, "o", "x"));
	}

	/** Branch: ?e unbound (the EXISTS expression errors) instead of false. */
	@Test
	public void bindExistsWithErroringBindInBodyIsFalse() throws Exception {
		load(":b :q :a .\n");
		String query = "SELECT ?o ?e WHERE { ?o :q ?z BIND(EXISTS { ?o :r ?y . BIND(?o + 1 AS ?s) } AS ?e) }";
		assertEquals(List.of("o=http://ex/b e=\"false\"^^<http://www.w3.org/2001/XMLSchema#boolean>"),
				rows(query, "o", "e"));
	}

	/**
	 * Branch: one row. The MINUS right side keeps {x=:a, z="a", o="a"} because the NOT EXISTS body (BIND("a" + 1)
	 * leaves ?y unbound, and there is no :r triple) is empty; that row is compatible with the left row and removes it.
	 */
	@Test
	public void bindErrorInsideNotExistsWithinMinusStillRemovesCompatibleRow() throws Exception {
		load(":a :p \"a\" .\n");
		String query = "SELECT ?s ?z WHERE { ?s :p ?z . MINUS { ?x :p ?z . BIND(COALESCE(?z, \"d\") AS ?o)"
				+ " FILTER NOT EXISTS { BIND(?o + 1 AS ?y) ?y :r ?x . } } }";
		assertEquals(List.of(), rows(query, "s", "z"));
	}

	/** Branch: ValueExprEvaluationException from the OPTIONAL condition {@code ?z + 1 = 2} with ?z = :b. */
	@Test
	public void erroringOptionalConditionInsideExistsIsFalseNotAnException() throws Exception {
		load(":b :p \"b\" .\n:g { :b :p \"c\" . }\n");
		String query = "SELECT ?z ?o WHERE { ?z :p ?o . FILTER EXISTS { GRAPH ?g { ?z :p ?y ."
				+ " OPTIONAL { :b :p ?o . FILTER((?o = \"a\"@EN && ?z + 1 = 2)) } } } }";
		// the GRAPH :g body matches (:b :p "c"); the OPTIONAL condition errors -> false -> the OPTIONAL row is
		// dropped but the left solution remains, so EXISTS holds for both outer rows
		assertEquals(List.of("z=http://ex/b o=\"b\"", "z=http://ex/b o=\"c\""), rows(query, "z", "o"));
	}
}
